-- READ-ONLY: definitions of live functions with no CREATE in supabase/ (135). Changes nothing.
select n.nspname, p.proname, pg_get_function_identity_arguments(p.oid) args, pg_get_functiondef(p.oid) def
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where p.prokind='f' and (n.nspname in ('legacy_dashboard','performance_private')
 or (n.nspname='clinic_reception' and p.proname = any(string_to_array('capture_diagnostic_followup,diagnostic_result_type,journey_event_exists,order_ext_status_guard,publish_diagnostic_result,sync_queue_from_appointment',',')))
 or (n.nspname='public' and p.proname = any(string_to_array('administrative_assistant_payroll_audit,agent_match_patients_by_phone,ai_clip_auto_enqueue,ai_clip_cancel,ai_clip_overview,ai_clip_request,ai_clip_save_settings,capture_administrative_assistant_mention,claude_autoschedule_approved,clinic_finance_insurance_claim_v2,clinic_info_access,clinic_info_edit,clinic_reception_agent_context,clinic_reception_agent_event,clinic_reception_agent_health,clinic_reception_agent_set_communications,clinic_reception_call_command,clinic_reception_call_command_live,clinic_reception_calls_snapshot,clinic_reception_calls_snapshot_live,clinic_reception_checkin_candidates,clinic_reception_checkin_public,clinic_reception_checkin_static,clinic_reception_journey_prepare_finish,clinic_reception_journey_request_service,clinic_reception_journey_reschedule,clinic_reception_journey_reschedule_slots,clinic_reception_journey_snapshot,clinic_reception_pbx_event,clinic_reception_so_attach,clinic_reception_so_attach_report,clinic_reception_so_can_read_staff,clinic_reception_so_can_upload,clinic_reception_so_catalog,clinic_reception_so_notify_prepare,clinic_reception_so_notify_result,clinic_reception_so_orders_list,clinic_reception_so_path_ok,clinic_reception_so_patient_can_read,clinic_reception_so_provider_board,clinic_reception_so_register_report,clinic_reception_so_reports,clinic_reception_so_set_status,clinic_reception_so_setup_load,clinic_reception_so_setup_save,content_learning_brief,content_learning_brief_core,content_learning_brief_staff,content_performance,hub_admin_list,hub_admin_set,hub_my_cards,hub_public_cards,insurance_bill_visit,insurance_billable_visits,insurance_claims_workspace,insurance_command,insurance_contract_options,insurance_open_shifts,insurance_patient_context,insurance_patient_link_set,insurance_quote,insurance_visit_billing_context,insurance_workspace,meta_job_retry,meta_publish_issues,meta_requeue_retryable_jobs,my_staff_kpis,patient_portal_journey_action,patient_port